begin;
-- Static PDF backgrounds and mappings are immutable; no signature is fabricated.
create table private.pdf_template_assets(id uuid primary key,company_id uuid not null references public.companies(id),created_by uuid not null references auth.users(id),filename text not null,sha256 text not null check(sha256 ~ '^[a-f0-9]{64}$'),byte_size integer not null check(byte_size between 5 and 4194304),pages jsonb not null,object_path text not null unique,created_at timestamptz not null default clock_timestamp(),unique(company_id,id));
create table private.pdf_template_versions(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id),template_id uuid not null,version integer not null check(version>0),asset_id uuid not null,title text not null,fields jsonb not null,created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),foreign key(company_id,asset_id)references private.pdf_template_assets(company_id,id),unique(company_id,template_id,version),unique(company_id,id));
create table private.pdf_template_requests(actor_id uuid not null references auth.users(id),request_id uuid not null,payload jsonb not null,version_id uuid not null references private.pdf_template_versions(id),primary key(actor_id,request_id));
create table private.pdf_template_generations(source_id uuid primary key,company_id uuid not null references public.companies(id),deal_id uuid not null,template_version_id uuid not null,actor_id uuid not null references auth.users(id),request_id uuid not null,customer_id uuid not null,customer_version integer not null,stock_item_id uuid not null,sale_price_ore bigint not null,data jsonb not null,data_sha256 text not null,created_at timestamptz not null default clock_timestamp(),foreign key(company_id,deal_id)references public.deals(company_id,id),foreign key(company_id,template_version_id)references private.pdf_template_versions(company_id,id),unique(actor_id,request_id));
create table private.pdf_template_source_lineage(source_id uuid primary key references private.uploaded_pdf_sources(id),template_version_id uuid not null references private.pdf_template_versions(id),template_sha256 text not null,mapping_sha256 text not null,data_sha256 text not null,generated_pdf_sha256 text not null,created_at timestamptz not null default clock_timestamp());
create index pdf_template_versions_company_order on private.pdf_template_versions(company_id,created_at desc,id desc);
create index pdf_template_generations_deal on private.pdf_template_generations(company_id,deal_id);
do $$declare t text;begin foreach t in array array['pdf_template_assets','pdf_template_versions','pdf_template_requests','pdf_template_generations','pdf_template_source_lineage']loop execute format('alter table private.%I enable row level security',t);execute format('revoke all on private.%I from public,anon,authenticated,service_role',t);execute format('create trigger %I before update or delete on private.%I for each row execute function private.sale_contract_immutable()',t||'_immutable',t);end loop;end$$;
create function private.pdf_template_asset_json(a private.pdf_template_assets)returns jsonb language sql stable set search_path=''as $$select jsonb_build_object('id',a.id,'companyId',a.company_id,'filename',a.filename,'sha256',a.sha256,'byteSize',a.byte_size,'pageCount',jsonb_array_length(a.pages),'pages',a.pages);$$;
create function private.pdf_template_version_json(v private.pdf_template_versions)returns jsonb language sql stable set search_path=''as $$select jsonb_build_object('id',v.id,'companyId',v.company_id,'templateId',v.template_id,'version',v.version,'title',v.title,'asset',private.pdf_template_asset_json(a),'fields',v.fields,'createdAt',v.created_at)from private.pdf_template_assets a where a.company_id=v.company_id and a.id=v.asset_id;$$;
create function private.pdf_template_mapping_valid(fields jsonb,pages jsonb)returns boolean language plpgsql immutable set search_path=''as $$declare f jsonb;g jsonb;p jsonb;seen text[]:='{}';k text;begin
 if jsonb_typeof(fields)is distinct from'array'or jsonb_array_length(fields)not between 1 and 60 or jsonb_typeof(pages)is distinct from'array'or jsonb_array_length(pages)not between 1 and 100 then return false;end if;
 for f in select value from jsonb_array_elements(fields)loop
 if jsonb_typeof(f)is distinct from'object'or(f-array['id','key','pageIndex','x','y','width','height','fontSize'])<>'{}'::jsonb or coalesce(f->>'id','')!~'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$'or f->>'id'=any(seen)or not(coalesce(f->>'key','')=any(array['customer.name','customer.email','customer.phone','customer.address','customer.identity','vehicle.registration','vehicle.vin','vehicle.make','vehicle.model','vehicle.modelYear','vehicle.mileageKm','deal.price','company.name','company.organisationNumber']))then return false;end if;seen:=array_append(seen,f->>'id');
 foreach k in array array['pageIndex','x','y','width','height','fontSize']loop if jsonb_typeof(f->k)is distinct from'number'then return false;end if;end loop;
 if(f->>'pageIndex')!~'^[0-9]{1,2}$'or(f->>'pageIndex')::integer>=jsonb_array_length(pages)then return false;end if;p:=pages->((f->>'pageIndex')::integer);
 if(f->>'x')::numeric<0 or(f->>'y')::numeric<0 or(f->>'width')::numeric<=0 or(f->>'height')::numeric<=0 or(f->>'x')::numeric+(f->>'width')::numeric>1 or(f->>'y')::numeric+(f->>'height')::numeric>1 or(f->>'fontSize')::numeric not between 8 and 32 or(f->>'width')::numeric*(p->>'width')::numeric<8 or(f->>'height')::numeric*(p->>'height')::numeric<(f->>'fontSize')::numeric*1.2 then return false;end if;
 for g in select value from jsonb_array_elements(fields)loop if f->>'id'<>g->>'id' and f->>'pageIndex'=g->>'pageIndex' and(f->>'x')::numeric<(g->>'x')::numeric+(g->>'width')::numeric and(g->>'x')::numeric<(f->>'x')::numeric+(f->>'width')::numeric and(f->>'y')::numeric<(g->>'y')::numeric+(g->>'height')::numeric and(g->>'y')::numeric<(f->>'y')::numeric+(f->>'height')::numeric then return false;end if;end loop;end loop;return true;exception when others then return false;end$$;
create function public.register_pdf_template_asset(p_actor_id uuid,p_company_id uuid,p_asset_id uuid,p_filename text,p_sha256 text,p_byte_size integer,p_pages jsonb)returns jsonb language plpgsql security definer set search_path=''as $$declare a private.pdf_template_assets;p jsonb;path text;begin perform private.uploaded_pdf_service();if not private.uploaded_pdf_actor_valid(p_company_id,p_actor_id)then raise exception'Actor denied'using errcode='42501';end if;
 if p_asset_id is null or p_filename is null or p_filename<>btrim(p_filename)or length(p_filename)not between 5 and 160 or p_filename~'[[:cntrl:]/\\]'or lower(right(p_filename,4))<>'.pdf'or p_sha256 is null or p_sha256!~'^[a-f0-9]{64}$'or p_byte_size is null or p_byte_size not between 5 and 4194304 or jsonb_typeof(p_pages)is distinct from'array'or jsonb_array_length(p_pages)not between 1 and 100 then raise exception'Invalid PDF template'using errcode='22023';end if;
 for p in select value from jsonb_array_elements(p_pages)loop if jsonb_typeof(p)is distinct from'object'or(p-array['width','height'])<>'{}'::jsonb or jsonb_typeof(p->'width')is distinct from'number'or jsonb_typeof(p->'height')is distinct from'number'or(p->>'width')::numeric not between 10 and 14400 or(p->>'height')::numeric not between 10 and 14400 then raise exception'Invalid PDF pages'using errcode='22023';end if;end loop;
 perform pg_advisory_xact_lock(hashtextextended('pdf-template-asset:'||p_asset_id::text,0));select*into a from private.pdf_template_assets where id=p_asset_id;if found then if a.company_id<>p_company_id or a.created_by<>p_actor_id or a.filename<>p_filename or a.sha256<>p_sha256 or a.byte_size<>p_byte_size or a.pages<>p_pages then raise exception'Asset request changed'using errcode='40001';end if;return private.pdf_template_asset_json(a);end if;
 path:=p_company_id::text||'/pdf-templates/'||p_asset_id::text||'/original-'||p_sha256||'.pdf';if not exists(select 1 from storage.objects where bucket_id='uploaded-contracts'and name=path)then raise exception'Original missing'using errcode='40001';end if;
 insert into private.pdf_template_assets(id,company_id,created_by,filename,sha256,byte_size,pages,object_path)values(p_asset_id,p_company_id,p_actor_id,p_filename,p_sha256,p_byte_size,p_pages,path)returning*into a;return private.pdf_template_asset_json(a);end$$;
create function public.get_pdf_template_asset(p_company_id uuid,p_asset_id uuid)returns jsonb language plpgsql security definer set search_path=''as $$declare actor uuid;a private.pdf_template_assets;begin actor:=private.uploaded_pdf_actor(p_company_id);select*into a from private.pdf_template_assets where company_id=p_company_id and id=p_asset_id;if not found then raise exception'Asset denied'using errcode='42501';end if;return jsonb_build_object('actorId',actor,'asset',private.pdf_template_asset_json(a));end$$;
create function public.list_pdf_template_versions(p_company_id uuid)returns jsonb language plpgsql security definer set search_path=''as $$declare a uuid;begin a:=private.uploaded_pdf_actor(p_company_id);return jsonb_build_object('actorId',a,'companyId',p_company_id,'templates',(select coalesce(jsonb_agg(private.pdf_template_version_json(v)order by v.created_at desc,v.id desc),'[]')from(select*from private.pdf_template_versions where company_id=p_company_id order by created_at desc,id desc limit 100)v));end$$;
create function public.save_pdf_template_version(p_company_id uuid,p_asset_id uuid,p_template_id uuid,p_expected_version integer,p_title text,p_fields jsonb,p_request_id uuid,p_acknowledged boolean)returns jsonb language plpgsql security definer set search_path=''as $$declare a uuid;asset private.pdf_template_assets;v private.pdf_template_versions;prior private.pdf_template_requests;payload jsonb;current_version integer;begin a:=private.uploaded_pdf_actor(p_company_id);
 if p_request_id is null or p_template_id is null or p_acknowledged is distinct from true or p_expected_version is null or p_expected_version<0 or p_title is null or p_title<>btrim(p_title)or length(p_title)not between 2 and 160 or p_title~'[[:cntrl:]]'then raise exception'Review required'using errcode='22023';end if;
 payload:=jsonb_build_object('companyId',p_company_id,'assetId',p_asset_id,'templateId',p_template_id,'expectedVersion',p_expected_version,'title',p_title,'fields',p_fields,'acknowledged',true);perform pg_advisory_xact_lock(hashtextextended('pdf-template-save:'||a::text||p_request_id::text,0));select*into prior from private.pdf_template_requests where actor_id=a and request_id=p_request_id;if found then if prior.payload<>payload then raise exception'Request changed'using errcode='40001';end if;select*into v from private.pdf_template_versions where id=prior.version_id;return jsonb_build_object('actorId',a,'template',private.pdf_template_version_json(v));end if;
 select*into asset from private.pdf_template_assets where company_id=p_company_id and id=p_asset_id;if not found then raise exception'Asset denied'using errcode='42501';end if;if not private.pdf_template_mapping_valid(p_fields,asset.pages)then raise exception'Invalid mapping'using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('pdf-template-family:'||p_company_id::text||p_template_id::text,0));select coalesce(max(version),0)into current_version from private.pdf_template_versions where company_id=p_company_id and template_id=p_template_id;if current_version<>p_expected_version then raise exception'Template version changed'using errcode='40001';end if;
 insert into private.pdf_template_versions(company_id,template_id,version,asset_id,title,fields,created_by)values(p_company_id,p_template_id,current_version+1,p_asset_id,p_title,p_fields,a)returning*into v;insert into private.pdf_template_requests values(a,p_request_id,payload,v.id);return jsonb_build_object('actorId',a,'template',private.pdf_template_version_json(v));end$$;
create function private.pdf_template_values(d public.deals,fields jsonb)returns jsonb language sql stable set search_path=''as $$select coalesce(jsonb_object_agg(k.key,all_values.v->k.key),'{}')from public.customers c join public.companies co on co.id=c.company_id join public.stock_items s on s.company_id=c.company_id and s.id=d.stock_item_id join public.vehicles v on v.company_id=s.company_id and v.id=s.vehicle_id left join private.customer_identity_numbers i on i.company_id=c.company_id and i.customer_id=c.id cross join lateral(select jsonb_build_object('customer.name',c.name,'customer.email',c.email,'customer.phone',c.phone,'customer.address',c.address,'customer.identity',i.identity_number,'company.name',co.name,'company.organisationNumber',co.organisation_number,'vehicle.registration',v.registration_number,'vehicle.vin',v.vin,'vehicle.make',v.make,'vehicle.model',v.model,'vehicle.modelYear',v.model_year::text,'vehicle.mileageKm',v.mileage_km::text,'deal.price',d.sale_price_ore::text)v)all_values cross join lateral(select distinct value->>'key'key from jsonb_array_elements(fields))k where c.company_id=d.company_id and c.id=d.customer_id;$$;
create function public.prepare_pdf_template_document(p_company_id uuid,p_deal_id uuid,p_template_version_id uuid,p_request_id uuid,p_acknowledged boolean)returns jsonb language plpgsql security definer set search_path=''as $$declare a uuid;d public.deals;c public.customers;v private.pdf_template_versions;g private.pdf_template_generations;data_values jsonb;begin a:=private.uploaded_pdf_actor(p_company_id);if p_acknowledged is distinct from true or p_request_id is null then raise exception'Review required'using errcode='22023';end if;
 if private.deal_is_archived(p_company_id,p_deal_id)then raise exception'Deal archived'using errcode='42501';end if;perform pg_advisory_xact_lock(hashtextextended('pdf-template-generation:'||a::text||p_request_id::text,0));select*into g from private.pdf_template_generations where actor_id=a and request_id=p_request_id;if found then if g.company_id<>p_company_id or g.deal_id<>p_deal_id or g.template_version_id<>p_template_version_id then raise exception'Generation changed'using errcode='40001';end if;else
 perform 1 from public.stock_items where company_id=p_company_id and id=(select stock_item_id from public.deals where company_id=p_company_id and id=p_deal_id) for update;select*into d from public.deals where company_id=p_company_id and id=p_deal_id for update;if not found or d.status not in('draft','reserved')or private.deal_is_archived(p_company_id,p_deal_id)then raise exception'Deal denied'using errcode='42501';end if;select*into c from public.customers where company_id=p_company_id and id=d.customer_id for share;
 select*into v from private.pdf_template_versions where company_id=p_company_id and id=p_template_version_id;if not found then raise exception'Template denied'using errcode='42501';end if;data_values:=private.pdf_template_values(d,v.fields);if exists(select 1 from jsonb_each(data_values)x where jsonb_typeof(x.value)is distinct from'string'or btrim(x.value#>>'{}')='')then raise exception'Mapped information missing'using errcode='22023';end if;
 insert into private.pdf_template_generations(source_id,company_id,deal_id,template_version_id,actor_id,request_id,customer_id,customer_version,stock_item_id,sale_price_ore,data,data_sha256)values(p_request_id,p_company_id,p_deal_id,p_template_version_id,a,p_request_id,c.id,c.contact_version,d.stock_item_id,d.sale_price_ore,data_values,encode(sha256(convert_to(data_values::text,'UTF8')),'hex'))returning*into g;end if;
 select*into v from private.pdf_template_versions where company_id=p_company_id and id=g.template_version_id;return jsonb_build_object('actorId',a,'sourceId',g.source_id,'companyId',g.company_id,'dealId',g.deal_id,'template',private.pdf_template_version_json(v),'data',g.data,'dataSha256',g.data_sha256,'createdAt',g.created_at);end$$;
create function public.register_pdf_template_document(p_actor_id uuid,p_company_id uuid,p_source_id uuid,p_sha256 text,p_byte_size integer,p_page_count integer)returns jsonb language plpgsql security definer set search_path=''as $$declare g private.pdf_template_generations;v private.pdf_template_versions;asset private.pdf_template_assets;d public.deals;c public.customers;s jsonb;l private.pdf_template_source_lineage;begin perform private.uploaded_pdf_service();perform 1 from public.companies where id=p_company_id for share;if not private.uploaded_pdf_actor_valid(p_company_id,p_actor_id)then raise exception'Actor denied'using errcode='42501';end if;select*into g from private.pdf_template_generations where source_id=p_source_id and company_id=p_company_id and actor_id=p_actor_id for update;if not found then raise exception'Generation denied'using errcode='42501';end if;
 select*into v from private.pdf_template_versions where company_id=p_company_id and id=g.template_version_id;select*into asset from private.pdf_template_assets where company_id=p_company_id and id=v.asset_id;select*into l from private.pdf_template_source_lineage where source_id=g.source_id;if found then if l.generated_pdf_sha256<>p_sha256 then raise exception'Generated PDF changed'using errcode='40001';end if;return private.uploaded_pdf_json((select x from private.uploaded_pdf_sources x where id=g.source_id));end if;
 perform 1 from public.stock_items where company_id=p_company_id and id=g.stock_item_id for update;select*into d from public.deals where company_id=p_company_id and id=g.deal_id for update;if not found or d.status not in('draft','reserved')or private.deal_is_archived(p_company_id,g.deal_id)or d.stock_item_id<>g.stock_item_id or d.customer_id<>g.customer_id or d.sale_price_ore<>g.sale_price_ore then raise exception'Deal changed during rendering'using errcode='40001';end if;select*into c from public.customers where company_id=p_company_id and id=g.customer_id for share;perform 1 from public.vehicles where company_id=p_company_id and id=(select vehicle_id from public.stock_items where company_id=p_company_id and id=g.stock_item_id) for share;if c.contact_version<>g.customer_version or private.pdf_template_values(d,v.fields)<>g.data then raise exception'Customer or vehicle changed during rendering'using errcode='40001';end if;
 s:=public.register_uploaded_pdf_source(p_actor_id,p_company_id,g.deal_id,g.source_id,'ifyllt-avtal-v'||v.version::text||'.pdf',p_sha256,p_byte_size,p_page_count);insert into private.pdf_template_source_lineage(source_id,template_version_id,template_sha256,mapping_sha256,data_sha256,generated_pdf_sha256)values(g.source_id,v.id,asset.sha256,encode(sha256(convert_to(v.fields::text,'UTF8')),'hex'),g.data_sha256,p_sha256);return s;end$$;
do $$declare f record;begin for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname like'pdf_template_%'loop execute format('revoke all on function %s from public,anon,authenticated,service_role',f.signature);end loop;end$$;
revoke all on function public.register_pdf_template_asset(uuid,uuid,uuid,text,text,integer,jsonb),public.register_pdf_template_document(uuid,uuid,uuid,text,integer,integer)from public,anon,authenticated;grant execute on function public.register_pdf_template_asset(uuid,uuid,uuid,text,text,integer,jsonb),public.register_pdf_template_document(uuid,uuid,uuid,text,integer,integer)to service_role;
revoke all on function public.get_pdf_template_asset(uuid,uuid),public.list_pdf_template_versions(uuid),public.save_pdf_template_version(uuid,uuid,uuid,integer,text,jsonb,uuid,boolean),public.prepare_pdf_template_document(uuid,uuid,uuid,uuid,boolean)from public,anon,service_role;grant execute on function public.get_pdf_template_asset(uuid,uuid),public.list_pdf_template_versions(uuid),public.save_pdf_template_version(uuid,uuid,uuid,integer,text,jsonb,uuid,boolean),public.prepare_pdf_template_document(uuid,uuid,uuid,uuid,boolean)to authenticated;
commit;
